rows, cols = 12, 18

def get_connected_regions(grid, target_val):
    regions = []
    visited = [[False]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_val and not visited[r][c]:
                region = []
                queue = [(r,c)]
                visited[r][c] = True

                idx = 0
                while idx < len(queue):
                    curr_r, curr_c = queue[idx]
                    idx += 1
                    region.append((curr_r, curr_c))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == target_val and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                regions.append(region)
    return regions

