def expand_all_directions(centers, radius):
    """Expand centers by Manhattan distance <= radius"""
    result = set()
    for cr, cc in centers:
        for dr in range(-radius, radius+1):
            for dc in range(-abs(dr), abs(dr)+1):
                r, c = cr + dr, cc + dc
                if 0 <= r < rows and 0 <= c < cols:
                    result.add((r, c))
    return result

def chebyshev_expand(centers, radius):
    """Chebyshev (square) distance <= radius"""
    result = set()
    for cr, cc in centers:
        for dr in range(-radius, radius+1):
            for dc in range(-radius, radius+1):
                r, c = cr + dr, cc + dc
                if 0 <= r < rows and 0 <= c < cols:
                    result.add((r, c))
    return result

def union_of_expansions(expansions):
    return set.union(*expansions)

