# Flood fill from ALL boundary cells (not just edges, but any cell touching boundary via path)
def flood_fill_unreachable(grid):
    """Find zero-cells unreachable from grid boundary using 4-way connectivity"""
    h, w = grid.shape
    visited = set()

    # Queue all boundary cells that are 0
    boundary_zeros = []
    for r in range(h):
        if grid[r][0] == 0: boundary_zeros.append((r, 0))
        if grid[r][w-1] == 0: boundary_zeros.append((r, w-1))
    for c in range(w):
        if grid[0][c] == 0: boundary_zeros.append((0, c))
        if grid[h-1][c] == 0: boundary_zeros.append((h-1, c))

    # BFS from boundary
    queue = list(boundary_zeros)
    idx = 0
    while idx < len(queue):
        r, c = queue[idx]
        idx += 1
        if (r, c) in visited: continue
        visited.add((r, c))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in visited:
                queue.append((nr, nc))

    # Return zeros NOT reached from boundary
    unreachable = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r,c) not in visited:
                unreachable.add((r, c))

    return unreachable

